on('#daily-form',(form)=>{const msg=msgFor(form);const dateEl=form.querySelector('[name=date]');if(!dateEl)return;dateEl.value=L.today;let filled=null;const fill=(ds)=>{const c=dash.data('days');if(c.status!=='ok')return;const r=(c.data||[]).find((x)=>x.date===ds);keys.forEach((k)=>{const i=form.querySelector(`[name=d_${k}]`);if(i)i.checked=!!(r&&r[k]===true);});form.querySelectorAll('[name=energy]').forEach((i)=>{i.checked=!!(r&&String(r.energy)===i.value);});const n=form.querySelector('[name=note]');if(n)n.value=r&&r.note?String(r.note):'';const wn=form.querySelector('[name=win]');if(wn)wn.value=r&&r.win?String(r.win):'';filled=ds;};const pick=()=>{if(!dateEl.value||!dateEl.validity.valid)return;L.day=dateEl.value;msg('day-saved',false);fill(dateEl.value);dash.draw('calendar');dash.draw('callabel');};dateEl.addEventListener('change',pick);dash.onData(()=>{if(filled===null&&dash.data('days').status==='ok')fill(dateEl.value);});form.addEventListener('input',(e)=>{if(e.target!==dateEl)msg('day-saved',false);});form.addEventListener('submit',async(e)=>{e.preventDefault();['day-saved','day-error','day-missing'].forEach((i)=>msg(i,false));const ds=dateEl.value;if(!ds||ds.length!==10){msg('day-missing',true);return;}const row={date:ds};keys.forEach((k)=>{const i=form.querySelector(`[name=d_${k}]`);row[k]=!!(i&&i.checked);});const en=form.querySelector('[name=energy]:checked');row.energy=en?Number(en.value):null;const n=form.querySelector('[name=note]');row.note=n?n.value.trim():'';const wn=form.querySelector('[name=win]');row.win=wn?wn.value.trim():'';row.savedAt=new Date().toISOString();const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{await L.save('days',ds,row);filled=ds;msg('day-saved',true);}catch(err){msg('day-error',true);}finally{if(btn)btn.disabled=false;}});});
on('#weekly-form',(form)=>{const msg=msgFor(form);const wEl=form.querySelector('[name=week]');if(!wEl)return;wEl.value=L.week;let filled=null;const fields=['score','win','blocker','next'];const fill=(wk)=>{const c=dash.data('weeks');if(c.status!=='ok')return;const r=(c.data||[]).find((x)=>x.week===wk);fields.forEach((f)=>{const i=form.querySelector(`[name=${f}]`);if(i)i.value=r&&r[f]!=null?String(r[f]):'';});filled=wk;};wEl.addEventListener('change',()=>{if(!wEl.value||!wEl.validity.valid)return;L.week=L.monday(wEl.value);msg('wk-saved',false);fill(L.week);dash.draw('weekgrid');dash.draw('weeklabel');});dash.onData(()=>{if(filled===null&&dash.data('weeks').status==='ok')fill(L.week);});form.addEventListener('input',(e)=>{if(e.target!==wEl)msg('wk-saved',false);});form.addEventListener('submit',async(e)=>{e.preventDefault();['wk-saved','wk-error','wk-missing'].forEach((i)=>msg(i,false));const s=form.querySelector('[name=score]');const v=s&&s.value!==''?Number(s.value):NaN;if(!Number.isInteger(v)||v<1||v>10){msg('wk-missing',true);return;}const row={week:L.week,score:v};['win','blocker','next'].forEach((f)=>{const i=form.querySelector(`[name=${f}]`);row[f]=i?i.value.trim():'';});row.savedAt=new Date().toISOString();const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{await L.save('weeks',L.week,row);filled=L.week;msg('wk-saved',true);}catch(err){msg('wk-error',true);}finally{if(btn)btn.disabled=false;}});});
on('#checkin-form',(form)=>{const msg=msgFor(form);const monthEl=form.querySelector('[name=month]');if(!monthEl)return;monthEl.value=L.today.slice(0,7);let filled=null;const notes=['win','god','focus'];const fill=(m)=>{const c=dash.data('checkins');if(c.status!=='ok')return;const r=(c.data||[]).find((x)=>x.month===m||x.id===m);keys.forEach((k)=>{const i=form.querySelector(`[name=${k}]`);if(i)i.value=r&&r[k]!=null?String(r[k]):'';});notes.forEach((f)=>{const t=form.querySelector(`[name=${f}]`);if(t)t.value=r&&r[f]?String(r[f]):'';});filled=m;};monthEl.addEventListener('change',()=>{msg('ci-saved',false);if(monthEl.value&&monthEl.validity.valid)fill(monthEl.value);});dash.onData(()=>{if(filled===null&&monthEl.value&&dash.data('checkins').status==='ok')fill(monthEl.value);});form.addEventListener('input',(e)=>{if(e.target!==monthEl)msg('ci-saved',false);});form.addEventListener('submit',async(e)=>{e.preventDefault();['ci-saved','ci-missing','ci-error'].forEach((i)=>msg(i,false));const m=monthEl.value;if(!m||m.length!==7||m[4]!=='-'){msg('ci-missing',true);return;}const row={month:m};let ok=true;keys.forEach((k)=>{const i=form.querySelector(`[name=${k}]`);const v=i&&i.value!==''?Number(i.value):NaN;if(!Number.isInteger(v)||v<1||v>10)ok=false;else row[k]=v;});if(!ok){msg('ci-missing',true);return;}notes.forEach((f)=>{const t=form.querySelector(`[name=${f}]`);row[f]=t?t.value.trim():'';});row.savedAt=new Date().toISOString();const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{await L.save('checkins',m,row);filled=m;msg('ci-saved',true);}catch(err){msg('ci-error',true);}finally{if(btn)btn.disabled=false;}});});
on('#goals',(sec)=>{const msg=msgFor(sec);const dirty=new Set();const fields=Array.from(sec.querySelectorAll('[data-goal]'));fields.forEach((f)=>f.addEventListener('input',()=>{dirty.add(f);msg('goals-saved',false);}));dash.onData(()=>{const g=dash.data('goals');if(g.status!=='ok')return;fields.forEach((f)=>{if(dirty.has(f)||document.activeElement===f)return;const r=(g.data||[]).find((x)=>x.id===f.dataset.goal);const v=r&&r[f.dataset.goalField]?String(r[f.dataset.goalField]):'';if(f.value!==v)f.value=v;});});sec.querySelectorAll('#save-goals').forEach((btn)=>btn.addEventListener('click',async()=>{msg('goals-saved',false);msg('goals-error',false);btn.disabled=true;try{for(const [k,label] of L.areas){const g=sec.querySelector(`[data-goal=${k}][data-goal-field=goal]`);const a=sec.querySelector(`[data-goal=${k}][data-goal-field=action]`);await L.save('goals',k,{area:k,label:label,goal:g?g.value.trim():'',action:a?a.value.trim():''});}dirty.clear();msg('goals-saved',true);}catch(err){msg('goals-error',true);}finally{btn.disabled=false;}}));});
const shrink=async(file)=>{try{const url=URL.createObjectURL(file);const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url;});const sc=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*sc);c.height=Math.round(img.naturalHeight*sc);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);const b=await new Promise((r)=>c.toBlob(r,'image/jpeg',0.85));return b||file;}catch(e){return file;}};
on('#memory-form',(form)=>{const msg=msgFor(form);const dEl=form.querySelector('[name=date]');if(dEl){dEl.value=L.today;}claude.use('assets').then((a)=>{if(!a)form.querySelectorAll('.lg-photo-field').forEach((el)=>{el.hidden=true;});});form.addEventListener('submit',async(e)=>{e.preventDefault();['mem-saved','mem-error','mem-missing'].forEach((i)=>msg(i,false));const fileEl=form.querySelector('[name=photo]');const titleEl=form.querySelector('[name=title]');const noteEl=form.querySelector('[name=note]');const file=fileEl&&fileEl.files&&fileEl.files[0];const title=titleEl?titleEl.value.trim():'';const note=noteEl?noteEl.value.trim():'';if(!file&&!title&&!note){msg('mem-missing',true);return;}const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{const row={date:dEl&&dEl.value?dEl.value:L.today,title:title,note:note,savedAt:new Date().toISOString()};if(file){const a=await claude.use('assets');if(!a)throw new Error('no assets');const up=await a.upload(await shrink(file));row.imageId=up.id;}await L.save('memories',null,row);[fileEl,titleEl,noteEl].forEach((i)=>{if(i)i.value='';});msg('mem-saved',true);}catch(err){msg('mem-error',true);}finally{if(btn)btn.disabled=false;}});});
on('#dump-form',(form)=>{const msg=msgFor(form);form.addEventListener('submit',async(e)=>{e.preventDefault();['dump-error','dump-missing'].forEach((i)=>msg(i,false));const t=form.querySelector('[name=text]');const ins=form.querySelector('[name=instead]');const text=t?t.value.trim():'';if(!text){msg('dump-missing',true);return;}const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{await L.save('letgo',null,{text:text,instead:ins?ins.value.trim():'',date:L.today,released:false});if(t)t.value='';if(ins)ins.value='';}catch(err){msg('dump-error',true);}finally{if(btn)btn.disabled=false;}});});on('#win-form',(form)=>{const msg=msgFor(form);const dEl=form.querySelector('[name=date]');if(dEl)dEl.value=L.today;form.addEventListener('submit',async(e)=>{e.preventDefault();['win-saved','win-error','win-missing'].forEach((i)=>msg(i,false));const t=form.querySelector('[name=text]');const a=form.querySelector('[name=area]');const text=t?t.value.trim():'';if(!text){msg('win-missing',true);return;}const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{await L.save('wins',null,{text:text,area:a?a.value:'',date:dEl&&dEl.value?dEl.value:L.today,savedAt:new Date().toISOString()});if(t)t.value='';msg('win-saved',true);}catch(err){msg('win-error',true);}finally{if(btn)btn.disabled=false;}});form.addEventListener('input',()=>msg('win-saved',false));});
on('#dream-unlock',(btn)=>btn.addEventListener('click',async()=>{const n=document.querySelector('#dream-name-input');const name=n?n.value.trim():'';btn.disabled=true;on('#dream-unlock-error',(p)=>{p.hidden=true;});try{const cur=L.rows('dream').find((x)=>x.id==='state');const row=Object.assign({},cur||{});delete row.id;row.unlocked=true;if(name)row.name=name;row.unlockedOn=row.unlockedOn||L.today;await L.save('dream','state',row);}catch(err){on('#dream-unlock-error',(p)=>{p.hidden=false;});}finally{btn.disabled=false;}}));
