on('.lg-dream-form',(form)=>{const h=form.dataset.h;const msg=(id,show)=>form.querySelectorAll('[data-msg='+id+']').forEach((p)=>{p.hidden=!show;});const fields=['who','feel','day','step'];let filled=false;const dirty=new Set();fields.forEach((f)=>{const i=form.querySelector(`[name=${f}]`);if(i)i.addEventListener('input',()=>{dirty.add(f);msg('saved',false);});});dash.onData(()=>{const d=dash.data('dream');if(d.status!=='ok')return;const r=(d.data||[]).find((x)=>x.id===h);fields.forEach((f)=>{const i=form.querySelector(`[name=${f}]`);if(!i||dirty.has(f)||document.activeElement===i)return;const v=r&&r[f]?String(r[f]):'';if(!filled||i.value!==v)i.value=v;});filled=true;});form.addEventListener('submit',async(e)=>{e.preventDefault();msg('saved',false);msg('error',false);msg('full',false);const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{const cur=L.rows('dream').find((x)=>x.id===h);const row=Object.assign({horizon:h},cur||{});delete row.id;fields.forEach((f)=>{const i=form.querySelector(`[name=${f}]`);row[f]=i?i.value.trim():'';});const photos=Array.isArray(row.photos)?row.photos.slice():[];const fileEl=form.querySelector('[name=photos]');const files=fileEl&&fileEl.files?Array.from(fileEl.files):[];if(files.length){const a=await claude.use('assets');if(!a)throw new Error('no assets');for(const f of files){if(photos.length>=12){msg('full',true);break;}const up=await a.upload(await shrink(f));photos.push(up.id);}}row.photos=photos;row.savedAt=new Date().toISOString();await L.save('dream',h,row);if(fileEl)fileEl.value='';dirty.clear();msg('saved',true);}catch(err){msg('error',true);}finally{if(btn)btn.disabled=false;}});});
